guided-practice.solution:
def describe_stock(count):
    if count is None:
        return "unknown"
    elif count == 0:
        return "out of stock"
    else:
        return "in stock"

independent-practice.solution:
def bmi_category(bmi):
    if bmi < 18.5:
        return "under"
    elif bmi < 25:
        return "normal"
    elif bmi < 30:
        return "over"
    else:
        return "obese"

def shipping_cost(weight, is_member):
    if is_member and weight <= 2:
        return 0
    if weight > 10:
        return 8
    return 5

def is_leap_year(year):
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0

def display_name(nickname, full_name):
    if nickname:
        return nickname
    return full_name

def classify_triangle(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        return "not a triangle"
    if a + b <= c or a + c <= b or b + c <= a:
        return "not a triangle"
    if a == b and b == c:
        return "equilateral"
    if a == b or b == c or a == c:
        return "isosceles"
    return "scalene"

